import { randomUUID } from "node:crypto";
import { PLANS } from "@/lib/plans";
import { resolveUsagePeriods } from "@/lib/usage-periods";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { importUsageEvidence, withUsageTransaction } from "@/lib/usage-ledger";

describe.runIf(databaseTestsEnabled)("campaign quota reservations", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
    await setGating(fixture.db, true);
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  it("replays one campaign without reserving again and rolls back an oversized batch", async () => {
    const f = await usageOwner(boundary.db),
      input = await f.input(2);
    const a = await createCampaign(f.user.id, input),
      b = await createCampaign(f.user.id, input);
    expect(a.id).toBe(b.id);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id },
      }),
    ).toBe(2);
    await expect(
      createCampaign(f.user.id, await f.input(2)),
    ).rejects.toMatchObject({ allowance: "DAILY", remaining: 1 });
    expect(
      await boundary.db.campaign.count({ where: { userId: f.user.id } }),
    ).toBe(1);
    const sends = await boundary.db.send.findMany({
      where: { campaign: { userId: f.user.id } },
    });
    expect(
      sends.every(
        (s) =>
          +s.queueExpiresAt! - +s.createdAt <= 86400000 &&
          +s.queueExpiresAt! - +s.createdAt > 86399000,
      ),
    ).toBe(true);
  });
  for (const allowance of ["DAILY", "MONTHLY"] as const)
    it(`lets exactly one of 20 campaigns take the final ${allowance} slot`, async () => {
      const f = await usageOwner(boundary.db);
      if (allowance === "DAILY")
        await createCampaign(f.user.id, await f.input(2));
      else
        await withUsageTransaction(boundary.db, f.user.id, async (owner) => {
          const at = new Date();
          at.setUTCDate(1);
          at.setUTCHours(0, 0, 0, 0);
          for (let i = 0; i < 14; i++)
            await importUsageEvidence(owner, {
              sourceKey: `old:${i}`,
              deliveryKey: null,
              chargedAt: at,
              timestampSource: "sentAt",
            });
        });
      const inputs = [];
      for (let i = 0; i < 20; i++) inputs.push(await f.input());
      const results = await Promise.allSettled(
        inputs.map((input) => createCampaign(f.user.id, input)),
      );
      expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
      for (const r of results)
        if (r.status === "rejected")
          expect(r.reason).toMatchObject({ allowance, remaining: 0 });
      expect(
        await boundary.db.campaign.count({ where: { userId: f.user.id } }),
      ).toBe(allowance === "DAILY" ? 2 : 1);
    });
  describe.each([false, true])("repeat quotas (paid=%s)", (paid) => {
    async function priorDelivery(userId: string, email: string) {
      const deliveryKey = randomUUID();
      const sentAt = new Date("2025-01-01T00:00:00Z");
      await withUsageTransaction(boundary.db, userId, (owner) =>
        importUsageEvidence(owner, {
          sourceKey: deliveryKey,
          deliveryKey,
          chargedAt: sentAt,
          timestampSource: "sentAt",
        }),
      );
      await boundary.db.deliveryReceipt.create({
        data: {
          userId,
          deliveryKey,
          recipientEmail: email,
          createdAt: sentAt,
          sentAt,
        },
      });
    }
    for (const allowance of ["DAILY", "MONTHLY"] as const)
      it(`counts repeat sends toward the ${allowance} allowance`, async () => {
        const f = await usageOwner(boundary.db, { paid });
        const periods = resolveUsagePeriods(f.user);
        const input = await f.input();
        const contact = await boundary.db.contact.findFirstOrThrow({
          where: { id: input.recipientIds[0], userId: f.user.id },
        });
        await priorDelivery(f.user.id, contact.email);
        const period = allowance === "DAILY" ? periods.daily : periods.monthly;
        // One remaining slot accepts a repeat; the next repeat must fail.
        await withUsageTransaction(boundary.db, f.user.id, async (owner) => {
          for (let i = 0; i < period.limit - 1; i++)
            await importUsageEvidence(owner, {
              sourceKey: `repeat-quota:${i}`,
              deliveryKey: null,
              chargedAt: period.startsAt,
              timestampSource: "sentAt",
            });
        });
        const repeated = { ...input, resendIds: input.recipientIds };
        const campaign = await createCampaign(f.user.id, repeated);
        expect(campaign.count).toBe(1);
        expect((await createCampaign(f.user.id, repeated)).id).toBe(
          campaign.id,
        );
        const next = await f.input();
        const nextContact = await boundary.db.contact.findFirstOrThrow({
          where: { id: next.recipientIds[0], userId: f.user.id },
        });
        await priorDelivery(f.user.id, nextContact.email);
        await expect(
          createCampaign(f.user.id, { ...next, resendIds: next.recipientIds }),
        ).rejects.toMatchObject({ allowance, remaining: 0 });
        expect(
          await boundary.db.usageReservation.count({
            where: { userId: f.user.id, status: "RESERVED" },
          }),
        ).toBe(1);
      });
    it.each(["QUEUED", "ATTEMPTING", "UNCERTAIN"] as const)(
      "blocks an explicit repeat while delivery is %s",
      async (state) => {
        const f = await usageOwner(boundary.db, { paid });
        const input = await f.input();
        const campaign = await createCampaign(f.user.id, input);
        if (state !== "QUEUED")
          await boundary.db.send.updateMany({
            where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
            data: {
              deliveryState: state,
              ...(state === "UNCERTAIN" ? { status: "FAILED" as const } : {}),
            },
          });
        await expect(
          createCampaign(f.user.id, {
            ...input,
            idempotencyKey: randomUUID(),
            resendIds: input.recipientIds,
          }),
        ).rejects.toThrow("All selected contacts were skipped");
        expect(
          await boundary.db.campaign.count({ where: { userId: f.user.id } }),
        ).toBe(1);
      },
    );
    it("applies the campaign recipient cap to repeat sends", async () => {
      const f = await usageOwner(boundary.db, { paid });
      const cap = PLANS[paid ? "PAID" : "FREE"].campaignRecipients;
      const input = await f.input(cap + 1);
      await expect(
        createCampaign(f.user.id, { ...input, resendIds: input.recipientIds }),
      ).rejects.toMatchObject(
        paid ? { name: "ZodError" } : { code: "CAMPAIGN_RECIPIENT_LIMIT" },
      );
      expect(
        await boundary.db.campaign.count({ where: { userId: f.user.id } }),
      ).toBe(0);
    });
  });
  it("fails closed for historical owners without a checkpoint and initializes a genuinely new owner", async () => {
    const old = await usageOwner(boundary.db, { ready: false });
    await boundary.db.deliveryReceipt.create({
      data: {
        userId: old.user.id,
        recipientEmail: "[REDACTED_EMAIL]",
        createdAt: new Date(),
        sentAt: new Date(),
      },
    });
    await expect(
      createCampaign(old.user.id, await old.input()),
    ).rejects.toMatchObject({ code: "USAGE_NOT_READY" });
    const fresh = await usageOwner(boundary.db, { ready: false });
    await createCampaign(fresh.user.id, await fresh.input());
    expect(
      await boundary.db.user.findUnique({ where: { id: fresh.user.id } }),
    ).toMatchObject({ usageBackfillVersion: 1 });
  });
});
